# 3-Way Comparison: Observations vs MATLAB vs Octave (Temp+SMC Fix)
# ============================================================

library(tidyverse)
library(lubridate)

project_root <- getwd()
obs_file <- file.path(project_root, "2026Contributions/EC_DWD_ROTH_clean.rds")

# Find the latest TempSMC output directory
output_dirs <- list.dirs(file.path(project_root, "rSTEMMUS_SCOPE/output"), recursive = FALSE)
octave_dir <- tail(sort(grep("FIXED_TempSMC_6mo_OCTAVE", output_dirs, value = TRUE)), 1)
octave_theta_file <- file.path(octave_dir, "Sim_Theta.csv")

matlab_theta_file <- file.path(project_root, "2026Contributions/validation_plots/Sim_Theta.csv")

# Output to NEW separate folder for comparison
output_dir <- file.path(project_root, "2026Contributions/validation_plots_6mo_TempFix")
if (!dir.exists(output_dir)) dir.create(output_dir, recursive = TRUE)

cat("===================================================================\n")
cat("  6-MONTH COMPARISON: TEMP+SMC FIX vs MATLAB vs OBSERVATIONS      \n")
cat("===================================================================\n\n")
cat("Octave output:", octave_dir, "\n")
cat("MATLAB output:", matlab_theta_file, "\n")
cat("Output folder:", output_dir, "\n\n")

# --- Helper ---
extract_smc_60cm <- function(theta_file, label) {
  raw <- read.csv(theta_file, header = FALSE)
  depths <- as.numeric(raw[1, ])
  idx_60cm <- which(depths == 60)
  if (length(idx_60cm) == 0) idx_60cm <- which.min(abs(depths - 60))
  smc_values <- as.numeric(raw[-(1:3), idx_60cm])
  cat(sprintf("  %s: %d timesteps, range: %.4f to %.4f\n",
              label, length(smc_values), min(smc_values), max(smc_values)))
  return(smc_values)
}

# --- Load Data ---
obs <- readRDS(obs_file)
obs_filtered <- obs %>%
  filter(timestamp >= as.POSIXct("2019-01-01 00:00:00", tz = "UTC"),
         timestamp <= as.POSIXct("2019-06-30 23:00:00", tz = "UTC")) %>%
  select(timestamp, obs_SMC_60cm = SMC_60cm, prec_mm) %>%
  mutate(obs_SMC_60cm = obs_SMC_60cm / 100)

cat("Observations:", nrow(obs_filtered), "rows\n")

cat("\nLoading Octave (Temp+SMC Fix)...\n")
octave_smc <- extract_smc_60cm(octave_theta_file, "Octave TempFix")
octave_start <- as.POSIXct("2019-01-01 00:00:00", tz = "UTC")
octave_df <- tibble(
  timestamp = octave_start + hours(0:(length(octave_smc) - 1)),
  octave_SMC_60cm = octave_smc
)

cat("\nLoading MATLAB...\n")
matlab_smc <- extract_smc_60cm(matlab_theta_file, "MATLAB")
matlab_start <- min(obs$timestamp)
matlab_df <- tibble(
  timestamp = matlab_start + hours(0:(length(matlab_smc) - 1)),
  matlab_SMC_60cm = matlab_smc
) %>%
  filter(timestamp >= as.POSIXct("2019-01-01 00:00:00", tz = "UTC"),
         timestamp <= as.POSIXct("2019-06-30 23:00:00", tz = "UTC"))

# --- Merge ---
comparison <- obs_filtered %>%
  left_join(octave_df, by = "timestamp") %>%
  left_join(matlab_df, by = "timestamp") %>%
  mutate(
    diff_oct_mat = octave_SMC_60cm - matlab_SMC_60cm,
    diff_oct_obs = octave_SMC_60cm - obs_SMC_60cm,
    diff_mat_obs = matlab_SMC_60cm - obs_SMC_60cm,
    hour = hour(timestamp),
    day = as.Date(timestamp),
    week = week(timestamp),
    month = month(timestamp, label = TRUE),
    timestep = row_number()
  )

valid_data <- comparison %>%
  filter(!is.na(obs_SMC_60cm), !is.na(octave_SMC_60cm), !is.na(matlab_SMC_60cm))

cat("\nMatched timesteps:", nrow(valid_data), "\n")

# --- Initial Value Check ---
cat("\n===== INITIAL VALUE CHECK =====\n")
cat(sprintf("  Observations (t=0): %.4f\n", comparison$obs_SMC_60cm[1]))
cat(sprintf("  MATLAB (t=0):       %.4f\n", comparison$matlab_SMC_60cm[1]))
cat(sprintf("  Octave TempFix (t=0): %.4f\n", comparison$octave_SMC_60cm[1]))

# --- Summary Stats ---
summary_stats <- valid_data %>%
  summarise(
    obs_mean = mean(obs_SMC_60cm, na.rm = TRUE),
    octave_mean = mean(octave_SMC_60cm, na.rm = TRUE),
    matlab_mean = mean(matlab_SMC_60cm, na.rm = TRUE),
    oct_mat_bias = mean(diff_oct_mat, na.rm = TRUE),
    oct_mat_rmse = sqrt(mean(diff_oct_mat^2, na.rm = TRUE)),
    oct_mat_r = cor(octave_SMC_60cm, matlab_SMC_60cm, use = "complete.obs"),
    oct_obs_rmse = sqrt(mean(diff_oct_obs^2, na.rm = TRUE)),
    mat_obs_rmse = sqrt(mean(diff_mat_obs^2, na.rm = TRUE))
  )

cat("\n===== STATISTICS =====\n")
cat(sprintf("Octave-MATLAB: Bias=%+.4f  RMSE=%.4f  r=%.4f\n",
            summary_stats$oct_mat_bias, summary_stats$oct_mat_rmse, summary_stats$oct_mat_r))
cat(sprintf("Octave-Obs:    RMSE=%.4f\n", summary_stats$oct_obs_rmse))
cat(sprintf("MATLAB-Obs:    RMSE=%.4f\n", summary_stats$mat_obs_rmse))

# --- PLOT 1: 3-Way Time Series ---
