  pivot_longer(cols = c(obs_SMC_60cm, octave_SMC_60cm, matlab_SMC_60cm),
               names_to = "source", values_to = "SMC") %>%
  mutate(source = recode(source,
    obs_SMC_60cm = "Observations",
    octave_SMC_60cm = "Octave (Temp+SMC Fix)",
    matlab_SMC_60cm = "MATLAB")) %>%
  ggplot(aes(x = timestamp, y = SMC, color = source)) +
  geom_line(linewidth = 0.8, alpha = 0.85) +
  scale_color_manual(values = c(
    "Observations" = "black", "MATLAB" = "#2166AC", "Octave (Temp+SMC Fix)" = "#B2182B")) +
  labs(title = "3-Way Comparison: SMC 60cm (After Temperature Fix)",
       subtitle = "DE-STG | Jan-Jun 2019 | Octave with corrected initial temperatures",
       x = "Time", y = expression(paste("SMC (", m^3, "/", m^3, ")")), color = "Source") +
  theme_minimal(base_size = 13) +
  theme(legend.position = "bottom", plot.title = element_text(face = "bold", size = 15),
        panel.grid.minor = element_blank()) +
  coord_cartesian(ylim = c(0.05, 0.45))
ggsave(file.path(output_dir, "01_3way_SMC_60cm_timeseries.png"), p1, width = 14, height = 6, dpi = 150)
cat("\nSaved: 01\n")

