# --- PLOT 4: Rolling Difference ---
rollmean_simple <- function(x, k) {
  n <- length(x); result <- rep(NA, n)
  for (i in k:n) result[i] <- mean(x[(i-k+1):i], na.rm = TRUE)
  return(result)
}
df_rolling <- valid_data %>% mutate(rolling_diff = rollmean_simple(diff_oct_mat, 24))
p4 <- ggplot(df_rolling, aes(x = timestamp)) +
  geom_line(aes(y = rolling_diff), color = "#D6604D", linewidth = 0.8) +
  geom_hline(yintercept = 0, linetype = "dashed") +
  geom_hline(yintercept = c(-0.05, 0.05), linetype = "dotted", color = "gray50") +
  labs(title = "Rolling 24h Difference: Octave(TempFix) - MATLAB",
       x = "Time", y = expression(paste(Delta, " SMC"))) +
  theme_minimal(base_size = 13) + theme(plot.title = element_text(face = "bold"))
ggsave(file.path(output_dir, "04_rolling_difference.png"), p4, width = 14, height = 5, dpi = 150)
