# --- Verify soil_init.mat temperatures ---
cat("\n===== soil_init.mat VERIFICATION =====\n")
tryCatch({
  library(rhdf5)
  run_dirs <- list.dirs(file.path(project_root, "rSTEMMUS_SCOPE/runs"), recursive = FALSE)
  new_run_dir <- tail(sort(grep("FIXED_TempSMC", run_dirs, value = TRUE)), 1)
  if (length(new_run_dir) > 0) {
    f <- h5read(file.path(new_run_dir, "soil_init.mat"), "/")
    cat(sprintf("  Tss=%.2f (should be ~6.3, NOT -267)\n", f$Tss))
    cat(sprintf("  InitT0=%.2f  InitT4=%.2f\n", f$InitT0, f$InitT4))
    cat(sprintf("  InitX0=%.4f  InitX4=%.4f  BtmX=%.4f\n", f$InitX0, f$InitX4, f$BtmX))
    h5closeAll()
  }
}, error = function(e) cat("Error reading soil_init.mat:", e$message, "\n"))

# --- Final verdict ---
cat("\n===== COMPARISON: BEFORE vs AFTER TEMP FIX =====\n")
cat(sprintf("  Previous RMSE (Octave broken temp vs MATLAB): 0.1118\n"))
